-wrap:wrap}.duplicate-empty{padding:45px;text-align:center;background:#fff;border:1px solid var(--line);border-radius:14px;color:var(--muted)}@media(max-width:650px){.duplicate-head{display:block}.duplicate-stats{flex-wrap:wrap}.duplicate-row{grid-template-columns:22px 100px minmax(0,1fr);gap:8px}.duplicate-thumb{width:100px}.duplicate-toolbar{top:64px;align-items:flex-start;flex-direction:column}}
