@if($duplicates->isEmpty())<div class="duplicate-empty">Tidak ditemukan video dengan judul duplicate.</div>@else<form id="manualDeleteForm" method="POST" action="{{ route('admin.videos.duplicates.delete') }}">@csrf @method('DELETE')<div id="manualInputs"></div></form><form id="recommendedDeleteForm" method="POST" action="{{ route('admin.videos.duplicates.recommended-all') }}">@csrf @method('DELETE')<div id="recommendedInputs"></div></form><div class="duplicate-toolbar"><div><label><input type="checkbox" id="selectAllDuplicates"> SELECT ALL</label><strong id="selectedCount">SELECTED: 0 VIDEOS</strong><p class="selection-note" style="margin:3px 0 0">Select Recommended hanya memilih video KEEP dan tidak menghapusnya.</p></div><div class="group-actions"><button class="btn ghost" type="button" id="selectRecommended">SELECT RECOMMENDED</button><button class="btn ghost" type="button" id="clearSelection">CLEAR SELECTION</button><button class="btn danger" id="deleteSelected" type="button" disabled>DELETE SELECTED</button><button class="btn primary" id="deleteAccording" type="button">DELETE ACCORDING TO RECOMMENDATION</button></div></div>@foreach($duplicates as $group)<section class="duplicate-group" data-group="{{ $group['normalized'] }}"><h2>{{ $group['title'] }}</h2><p>{{ $group['count'] }} duplicate videos · Recommended: KEEP ID {{ $group['keep'] }}</p>@foreach($group['videos'] as $video)<label class="duplicate-row {{ $video->id === $group['keep'] ? 'recommended' : 'to-delete' }}" data-id="{{ $video->id }}" data-keep="{{ $video->id === $group['keep'] ? '1' : '0' }}"><input type="checkbox" value="{{ $video->id }}" class="duplicate-checkbox"><span>@if($video->thumbnail_url)<img class="duplicate-thumb" loading="lazy" src="{{ $video->thumbnail_url }}" alt="">@elseif(\Illuminate\Support\Facades\Storage::disk('public')->exists('thumbnails/'.$video->id.'.jpg'))<img class="duplicate-thumb" loading="lazy" src="{{ route('videos.thumbnail',$video) }}" alt="">@else<div class="duplicate-thumb"></div>@endif</span><span class="duplicate-details">@if($video->id === $group['keep'])<span class="badge keep">RECOMMENDED TO KEEP</span>@else<span class="badge delete">DUPLICATE</span>@endif<strong>{{ $video->title }}</strong><small>ID: {{ $video->id }} · {{ $video->categories->pluck('name')->join(', ') ?: 'Tanpa kategori' }} · {{ $video->models->pluck('name')->join(', ') ?: 'Tanpa model' }} · {{ $video->duration ?: '--:--' }}</small><small>{{ $video->file_available ? 'File tersedia' : 'File tidak ditemukan' }} · {{ $video->created_at?->format('d M Y H:i') }}</small></span></label>@endforeach<div class="group-actions"><span class="selection-note">Reason: {{ $group['reason'] }}</span><button class="btn ghost keep-this" type="button" data-group="{{ $group['normalized'] }}">KEEP THIS (recommended)</button><button class="btn danger delete-group" type="button" data-group="{{ $group['normalized'] }}" data-title="{{ $group['title'] }}">DELETE DUPLICATES</button></div></section>@endforeach</div>@endif</div>
<script>const selectedVideoIds=new Set();const checkboxes=[...document.querySelectorAll('.duplicate-checkbox')];const all=document.getElementById('selectAllDuplicates');const count=document.getElementById('selectedCount');const deleteSelected=document.getElementById('deleteSelected');const updateSelection=()=>{checkboxes.forEach(box=>box.checked=selectedVideoIds.has(Number(box.value)));const n=selectedVideoIds.size;count.textContent=`SELECTED: ${n} VIDEO${n===1?'':'S'}`;deleteSelected.disabled=n===0;all.checked=checkboxes.length>0&&n===checkboxes.length;all.indeterminate=n>0&&n<checkboxes.length};checkboxes.forEach(box=>box.addEventListener('change',()=>{const id=Number(box.value);box.checked?selectedVideoIds.add(id):selectedVideoIds.delete(id);updateSelection()}));all.addEventListener('change',()=>{checkboxes.forEach(box=>all.checked?selectedVideoIds.add(Number(box.value)):selectedVideoIds.delete(Number(box.value)));updateSelection()});document.getElementById('clearSelection').onclick=()=>{selectedVideoIds.clear();updateSelection()};document.getElementById('selectRecommended').onclick=()=>{document.querySelectorAll('.duplicate-row[data-keep="1"] input').forEach(box=>selectedVideoIds.add(Number(box.value)));updateSelection()};const submitManual=()=>{const form=document.getElementById('manualDeleteForm'),holder=document.getElementById('manualInputs');holder.innerHTML='';selectedVideoIds.forEach(id=>{const input=document.createElement('input');input.type='hidden';input.name='video_ids[]';input.value=id;holder.append(input)});if(!selectedVideoIds.size||!confirm(`DELETE ${selectedVideoIds.size} VIDEOS?\n\nTindakan ini tidak dapat dibatalkan.`))return;form.submit()};deleteSelected.onclick=submitManual;document.querySelectorAll('.keep-this').forEach(button=>button.onclick=()=>{const group=document.querySelector(`.duplicate-group[data-group="${CSS.escape(button.dataset.group)}"]`);group.querySelectorAll('.duplicate-row').forEach(row=>{row.classList.toggle('recommended',row.querySelector('input').value===group.querySelector('.duplicate-row[data-keep="1"] input').value);row.classList.toggle('to-delete',row.querySelector('input').value!==group.querySelector('.duplicate-row[data-keep="1"] input').value)});});document.querySelectorAll('.delete-group').forEach(button=>button.onclick=()=>{const group=document.querySelector(`.duplicate-group[data-group="${CSS.escape(button.dataset.group)}"]`);const keep=group.querySelector('.duplicate-row[data-keep="1"] input').value;const deletes=[...group.querySelectorAll('.duplicate-row:not([data-keep="1"]) input')].map(input=>input.value);const form=document.getElementById('recommendedDeleteForm'),holder=document.getElementById('recommendedInputs');holder.innerHTML=`<input type="hidden" name="keep_id" value="${keep}">${deletes.map(id=>`<input type="hidden" name="delete_ids[]" value="${id}">`).join('')}`;if(confirm(`DELETE DUPLICATES?\n\nKEEP ID ${keep}\nDELETE ${deletes.length} duplicate(s)?`))form.action='{{ route('admin.videos.duplicates.recommended') }}',form.submit()});document.getElementById('deleteAccording').onclick=()=>{const keeps=[...document.querySelectorAll('.duplicate-row[data-keep="1"] input')].map(x=>x.value);const deletes=[...document.querySelectorAll('.duplicate-row:not([data-keep="1"]) input')].map(x=>x.value);const form=document.getElementById('recommendedDeleteForm'),holder=document.getElementById('recommendedInputs');holder.innerHTML=keeps.map(id=>`<input type="hidden" name="keep_ids[]" value="${id}">`).join('')+deletes.map(id=>`<input type="hidden" name="delete_ids[]" value="${id}">`).join('');if(confirm(`HAPUS SESUAI REKOMENDASI?\n\nKEEP ${keeps.length} video\nDELETE ${deletes.length} duplicate video?`))form.submit()};updateSelection();</script>
<script>document.querySelectorAll('.keep-this').forEach(button=>button.addEventListener('click',()=>{const group=document.querySelector(`.duplicate-group[data-group="${CSS.escape(button.dataset.group)}"]`);const clicked=group.querySelector('.duplicate-row.recommended')?.dataset.id||group.querySelector('.duplicate-row input:checked')?.value;if(!clicked)return;group.querySelectorAll('.duplicate-row').forEach(row=>{const keep=row.dataset.id===clicked;row.dataset.keep=keep?'1':'0';row.classList.toggle('recommended',keep);row.classList.toggle('to-delete',!keep);const badge=row.querySelector('.badge');if(badge){badge.className=`badge ${keep?'keep':'delete'}`;badge.textContent=keep?'RECOMMENDED TO KEEP':'DUPLICATE'}});button.textContent=`KEEP ID ${clicked}`})});</script>
